using System; using System.Collections.Generic; using CodexTrayStatus;
internal static class QuotaForecastSmoke { static void Check(bool ok,string message){if(!ok)throw new Exception(message);} public static int Main(){long now=DataFreshness.Now, cycle=now+3600000; AppSnapshot snapshot=new AppSnapshot{QuotaState=new DataState{Source="official",Delivery="updated",Scope="account",AccountKey="a",ObservationId="one",ObservedAt=now,IsNewObservation=true,IsComplete=true},Quota=new QuotaResult{Limits=new List<RateLimitWindow>{new RateLimitWindow{WindowKey="five",WindowSeconds=18000,ResetsAt=cycle,UsedPercent=50,RemainingPercent=50}}}}; QuotaHistoryResult h=new QuotaHistoryResult{Available=true}; h.Points.Add(new QuotaHistoryPoint{WindowKey="five",CycleEnd=cycle,ObservedAt=now-600000,UsedPercent=20});h.Points.Add(new QuotaHistoryPoint{WindowKey="five",CycleEnd=cycle,ObservedAt=now,UsedPercent=50}); QuotaForecast f=QuotaForecastService.Evaluate(h,snapshot,now)[0];Check(f.Status=="before_reset"&&f.UsedPercentPerHour>179,"steady consumption predicts before reset");h.Points[1].CycleEnd=cycle+1;Check(QuotaForecastService.Evaluate(h,snapshot,now)[0].Status=="insufficient","cross-cycle points are excluded");h.Points[1].CycleEnd=cycle;h.Points[1].UsedPercent=20;Check(QuotaForecastService.Evaluate(h,snapshot,now)[0].Status=="idle","idle period is not predicted");snapshot.QuotaState.ObservedAt=now-24L*60L*60L*1000L;Check(QuotaForecastService.Evaluate(h,snapshot,now).Count==0,"stale current quota suppresses prediction");Console.WriteLine("Quota forecast tests passed.");return 0;} }
